gav(){return"\u10d3\u10d0\u10d0\u10ed\u10d8\u10e0\u10d4\u10d7 \u10d1\u10dd\u10e0\u10d1\u10da\u10d8\u10e1 \u10db\u10d2\u10e0\u10eb\u10dc\u10dd\u10d1\u10d4\u10da\u10dd\u10d1\u10d0\u10e1"},
gb1(){return"\u10de\u10d0\u10e2\u10d0\u10e0\u10d0"},
gaG(){return"\u10e1\u10d0\u10e8\u10e3\u10d0\u10da\u10dd"},
