gcq(){return"\u10d3\u10d0\u10d0\u10e0\u10e5\u10db\u10d4\u10d7 \u10d3\u10d0\u10e1\u10d0\u10d9\u10e0\u10d0\u10d5\u10d8 \u10e1\u10d8\u10d0"},
gab(){return"\u10d2\u10d0\u10db\u10dd\u10e0\u10d8\u10ea\u10ee\u10d4\u10d7 \u10d3\u10d8\u10e0\u10d4\u10e5\u10e2\u10dd\u10e0\u10d8\u10d4\u10d1\u10d8"},
gbO(){return"\u10e1\u10d8\u10db\u10e6\u10d4\u10e0\u10d4\u10d1\u10d8\u10e1 \u10de\u10dd\u10d5\u10dc\u10d0\u2026"},
b2(a,b){return"\u10e9\u10d0\u10e2\u10d5\u10d8\u10e0\u10d7\u10e3\u10da\u10d8 \u10e1\u10d8\u10db\u10e6\u10d4\u10e0\u10d4\u10d1\u10d8: "+a+" / "+b},
bm(a){return"\u10dc\u10d0\u10db\u10e3\u10e8\u10d4\u10d5\u10e0\u10d4\u10d1\u10d8 \u10e5\u10d4\u10e8\u10d8\u10e0\u10d4\u10d1\u10e3\u10da\u10d8\u10d0: "+a},
