gbJ(){return"\u0416\u0430\u043d\u0440"},
gbK(){return"\u0422\u0435\u043a\u0441\u0442\u044b \u043f\u0435\u0441\u0435\u043d"},
gaV(){return"\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f"},
gbu(){return"\u0421\u043b\u0435\u0433\u043a\u0430 \u043f\u0435\u0440\u0435\u043c\u0435\u0441\u0442\u0438\u0442\u0435 \u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u043f\u0430\u043b\u0435\u0446 \u0432\u043e\u043a\u0440\u0443\u0433 \u0449\u0435\u043b\u0447\u043a\u0430, \u0447\u0442\u043e\u0431\u044b \u0432\u044b\u0434\u0435\u043b\u0438\u0442\u044c \u0430\u043b\u0444\u0430\u0432\u0438\u0442"},
gbq(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043a\u043d\u043e\u043f\u043a\u0443 \u0446\u0435\u043d\u0442\u0440\u0430, \u0447\u0442\u043e\u0431\u044b \u0432\u044b\u0431\u0440\u0430\u0442\u044c \u0432\u044b\u0434\u0435\u043b\u0435\u043d\u043d\u044b\u0439 \u0430\u043b\u0444\u0430\u0432\u0438\u0442"},
gc6(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u044d\u0442\u0443 \u043a\u043d\u043e\u043f\u043a\u0443, \u0447\u0442\u043e\u0431\u044b \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0441\u0442\u0432\u043e"},
gci(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u044d\u0442\u0443 \u043a\u043d\u043e\u043f\u043a\u0443, \u0447\u0442\u043e\u0431\u044b \u0443\u0434\u0430\u043b\u0438\u0442\u044c \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u0436"},
gbX(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u044d\u0442\u0443 \u043a\u043d\u043e\u043f\u043a\u0443, \u0447\u0442\u043e\u0431\u044b \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u043a\u043b\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0443 \u0438 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u0441 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430\u043c\u0438 \u043f\u043e\u0438\u0441\u043a\u0430"},
ga6(){return"\u0412\u0441\u0435 \u043f\u0435\u0441\u043d\u0438"},
gaz(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u0440\u0430\u0437\u043c\u0435\u0440 \u043a\u043e\u043b\u0435\u0441\u0430"},
gav(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043a\u043e\u043b\u0435\u0441\u0430"},
gb1(){return"\u041c\u0430\u043b\u0435\u043d\u044c\u043a\u0438\u0439"},
gaG(){return"\u0421\u0435\u0440\u0435\u0434\u0438\u043d\u0430"},
gbR(){return"\u0411\u043e\u043b\u044c\u0448\u043e\u0439"},
gcw(){return"\u041e\u0447\u0435\u043d\u044c \u043d\u0438\u0437\u043a\u0438\u0439"},
gbV(a){return"\u041d\u0438\u0437\u043a\u0438\u0439"},
gbQ(a){return"\u0412\u044b\u0441\u043e\u043a\u0438\u0439"},
gaS(){return"\u0413\u0440\u043e\u043c\u043a\u043e\u0441\u0442\u044c \u0440\u0435\u0436\u0438\u043c\u0430"},
gbl(){return"\u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435"},
gbj(){return"\u0421\u0438\u0441\u0442\u0435\u043c\u0430"},
gcq(){return"\u041f\u0435\u0440\u0435\u0438\u043c\u0435\u043d\u043e\u0432\u0430\u0442\u044c \u043f\u043b\u0435\u0439\u043b\u0438\u0441\u0442"},
gab(){return"\u0418\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u043a\u0430\u0442\u0430\u043b\u043e\u0433\u0438"},
gbO(){return"\u041f\u043e\u0438\u0441\u043a \u043f\u0435\u0441\u0435\u043d\u2026"},
b2(a,b){return"\u0417\u0430\u0433\u0440\u0443\u0436\u0435\u043d\u044b \u043f\u0435\u0441\u043d\u0438: "+a+" / "+b+"."},
bm(a){return"\u0418\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0435 \u0432 \u043a\u044d\u0448\u0435: "+a},
gaE(){return"\u041d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u043c\u0443\u0437\u044b\u043a\u0430\u043b\u044c\u043d\u0443\u044e \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0443. \u041f\u043e\u0436\u0430\u043b\u0443\u0439\u0441\u0442\u0430, \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u0435 \u043f\u043e\u043f\u044b\u0442\u043a\u0443."},
gaF(){return"\u041f\u043e\u0432\u0442\u043e\u0440\u043d\u043e"},
