gbs(){return"\u041d\u0430\u0442\u0438\u0441\u043d\u0456\u0442\u044c \u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u0443 \u043a\u043d\u043e\u043f\u043a\u0443, \u0449\u043e\u0431 \u043f\u0440\u043e\u0432\u0435\u0441\u0442\u0438 \u043a\u0440\u0443\u0433\u043e\u043e\u0431\u0456\u0433\u0443 \u0447\u0435\u0440\u0435\u0437 \u0441\u043c\u0443\u0433\u0443 \u043f\u043e\u0448\u0443\u043a\u0443, \u0441\u043a\u0440\u0443\u0431\u0435\u0440 -\u0441\u043c\u0443\u0436\u043a\u0443 \u0442\u0430 \u043f\u043e\u0432\u0437\u0443\u043d\u043e\u043a \u0434\u043b\u044f \u043f\u0435\u0440\u0435\u0442\u0430\u0441\u0443\u0432\u0430\u043d\u043d\u044f. \u041d\u0430\u0442\u0438\u0441\u043d\u0456\u0442\u044c \u0456 \u0443\u0442\u0440\u0438\u043c\u0443\u0439\u0442\u0435 \u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u0443 \u043a\u043d\u043e\u043f\u043a\u0443, \u0449\u043e\u0431 \u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438 \u0434\u043e\u0441\u0442\u0443\u043f \u0434\u043e \u0434\u043e\u0434\u0430\u0442\u043a\u043e\u0432\u0438\u0445 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0456\u0432."},
